"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["50182"],{36197(e){e.exports=JSON.parse('{"id":"FIN-169","slug":"capital-allocation","term":"Capital Allocation","also_known_as":[],"difficulty":"Beginner","definition":"Capital allocation is how a company decides to use its available money among competing options, such as investing in growth, buying other businesses, paying down debt or returning cash to shareholders.","explanation":["Every company has limited resources. Capital allocation is the process of choosing where those resources will create the most value over time.","The main options are investing in the existing business, for example new equipment or research; acquiring other companies; repaying debt; paying dividends; and buying back shares. Holding cash for future opportunities is also a choice.","Good capital allocation compares the expected return of each option with its risk and with the company\'s cost of capital. If new projects are expected to earn 15% and shareholders require 9%, investing in them adds value. If no such projects exist, returning cash to shareholders may be the better choice, letting them invest elsewhere.","Investors watch capital allocation closely, because it shapes a company\'s long-term success. A company that overpays for acquisitions or spends on low-return projects can destroy value even while growing in size. Many of the most successful companies are known for disciplined capital allocation."],"note":"","total":1500,"prev":{"slug":"capital-adequacy-ratio","term":"Capital Adequacy Ratio"},"next":{"slug":"capital-asset-pricing-model","term":"Capital Asset Pricing Model (CAPM)"}}')}}]);